// Before: completion handler hell
func fetchUser(completion: @escaping (Result<User, Error>) -> Void) {
    networkCall { result in
        completion(result)
    }
}

// After: clean async/await
func fetchUser() async throws -> User {
    let data = try await URLSession.shared.data(from: url)
    return try JSONDecoder().decode(User.self, from: data.0)
}

// Calling async code
Task {
    do {
        let user = try await fetchUser()
        print(user.name)
    } catch {
        print("Failed: \(error)")
    }
}

func fetchAllUsers(ids: [Int]) async throws -> [User] {
    try await withThrowingTaskGroup(of: User.self) { group in
        for id in ids {
            group.addTask {
                try await fetchUser(id: id)
            }
        }

        var users: [User] = []
        for try await user in group {
            users.append(user)
        }
        return users
    }
}

// All tasks are scoped — if the function is cancelled,
// every child task is automatically cancelled too.
let users = try await fetchAllUsers(ids: [1, 2, 3, 4, 5])

actor BankAccount {
    private var balance: Double = 0

    func deposit(_ amount: Double) {
        balance += amount  // safe — serialized
    }

    func withdraw(_ amount: Double) -> Bool {
        guard balance >= amount else { return false }
        balance -= amount
        return true
    }

    var currentBalance: Double { balance }
}

let account = BankAccount()

// Must use await from outside the actor
await account.deposit(100)
let success = await account.withdraw(50)
let bal = await account.currentBalance  // 50.0

// @MainActor for UI updates
@MainActor
func updateUI(with balance: Double) {
    balanceLabel.text = "\(balance)"
}
